            example: "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n  <title>Responsive Website</title>\n</head>\n<body>\n  <h1>Hello, World!</h1>\n</body>\n</html>",
            image: "",
            video: "",
            example_image: ""
