            example: ".sidebar {\n  display: none;\n}\n\n@media (min-width: 900px) {\n  .sidebar {\n    display: block;\n  }\n\n  .layout {\n    display: grid;\n    grid-template-columns: 250px 1fr;\n    gap: 24px;\n  }\n}",
            image: "",
            video: "",
            example_image: ""
