            example: "const fs = require('node:fs/promises');\n\nasync function saveFile() {\n  await fs.writeFile('hello.txt', 'Hello from Node.js!');\n  const content = await fs.readFile('hello.txt', 'utf8');\n  console.log(content);\n}\n\nsaveFile().catch(console.error);",
            image: "",
            video: "",
            example_image: ""
