            example:
              "function add(a, b) {\n  return a + b;\n}\n\n// Example using Vitest\nimport { expect, test } from \"vitest\";\n\ntest(\"adds two numbers\", () => {\n  expect(add(2, 3)).toBe(5);\n});",
