            example: "use std::env;\nuse std::process;\n\nfn run() -> Result<(), String> {\n    let mut args = env::args();\n    let program = args.next().unwrap_or_else(|| String::from(\"greet\"));\n\n    let name = match args.next() {\n        Some(value) if !value.trim().is_empty() => value,\n        _ => {\n            return Err(format!(\"Usage: {program} <name>\"));\n        }\n    };\n\n    if args.next().is_some() {\n        return Err(format!(\"Usage: {program} <name>\"));\n    }\n\n    println!(\"Hello, {name}! Welcome to Rust.\");\n    Ok(())\n}\n\nfn main() {\n    if let Err(error) = run() {\n        eprintln!(\"Error: {error}\");\n        process::exit(1);\n    }\n}\n\n// Create and run the project:\n// cargo new greet\n// Replace src/main.rs with this code.\n// cargo run -- Abubakar\n// Expected output: Hello, Abubakar! Welcome to Rust.",
