        classes: "Class 7+",
        qa: [
          { id: 1, question: "What Is Software Quality Assurance?", answer: "Software Quality Assurance involves planned activities and processes that help ensure software development and delivery meet quality requirements.", example: "A team follows coding standards and testing procedures for each release.", image: "", video: "", example_image: "" },
          { id: 2, question: "What Are Functional and Non-Functional Requirements?", answer: "Functional requirements describe what a system does. Non-functional requirements describe qualities such as performance, accessibility, security, and reliability.", example: "A login feature is functional; a requirement for fast, secure login is non-functional.", image: "", video: "", example_image: "" },
          { id: 3, question: "How Do You Write Test Scenarios?", answer: "Describe a situation or workflow that should be checked to determine whether the system behaves as expected.", example: "Test the scenario in which a registered user signs in with valid credentials.", image: "", video: "", example_image: "" },
          { id: 4, question: "How Do You Create Test Cases?", answer: "Specify the preconditions, input steps, expected results, and relevant test data for a particular check.", example: "Enter an invalid email into a sign-up form and verify that a helpful validation message appears.", image: "", video: "", example_image: "" },
          { id: 5, question: "What Is Manual Testing?", answer: "Manual testing involves a person executing test steps and comparing the actual behavior with the expected behavior.", example: "Manually check whether all navigation links open the correct pages.", image: "", video: "", example_image: "" },
          { id: 6, question: "How Do You Report Bugs Clearly?", answer: "Include a short title, reproduction steps, expected and actual results, relevant environment details, and supporting evidence when appropriate.", example: "Report that clicking Save twice creates duplicate records, with exact steps to reproduce it.", image: "", video: "", example_image: "" },
          { id: 7, question: "How Do You Test Forms and User Inputs?", answer: "Check valid and invalid values, required fields, length limits, unusual characters, error messages, and server-side validation.", example: "Test an email form with an empty value and an incorrectly formatted address.", image: "", video: "", example_image: "" },
          { id: 8, question: "What Is Automated Testing?", answer: "Automated testing uses software to execute checks and compare actual results with expected results.", example: "A test script checks that a calculator returns 5 for 2 + 3.", image: "", video: "", example_image: "" },
          { id: 9, question: "How Do You Check Usability, Accessibility, and Performance?", answer: "Observe users completing tasks, check accessibility requirements, and measure loading times and responsiveness under appropriate conditions.", example: "Check keyboard navigation and measure how long a lesson page takes to load.", image: "", video: "", example_image: "" },
          { id: 10, question: "How Do You Test and Document a Website Release?", answer: "Run planned tests, record results and defects, verify fixes, check important security and usability requirements, and document release readiness.", example: "Prepare a release checklist covering login, forms, mobile layout, and important links.", image: "", video: "", example_image: "" }
        ]
