export function getLesson(courseId: string, index: number): Lesson {
  const course = courses.find((c) => c.id === courseId) ?? courses[0];
  const title = course.topics[index] ?? course.topics[0];
  const bank = lessonBank[title] ?? {
    explanation: `${title} is an important idea in ${course.title}. In this lesson you'll learn what it means, why it matters, and how it's used in real life — explained step by step in simple words.`,
    example: `Think about how ${title.toLowerCase()} shows up when you use a phone, play a game, or browse the internet.`,
    quiz: { q: `Which course is "${title}" part of?`, options: [course.title, "Cooking", "Gardening", "Painting"], answer: 0 },
  };
  return { id: `${course.id}--${index}`, title, xp: 50, ...bank };
}

